  TimePicker,
  TimePickerSelect,
  SelectItem,
} from 'carbon-components-react';

function App() {
  return (
    <div style={{ display: 'grid', rowGap: '2rem', padding: '2rem' }}>
      {/* small: expecting 32px but still 40px */}
      <TimePicker labelText="Choose a time" size="sm">
        <TimePickerSelect id="tp-sm-select-1" defaultValue="AM">
          <SelectItem value="AM" text="AM" />
          <SelectItem value="PM" text="PM" />
        </TimePickerSelect>
        <TimePickerSelect id="tp-sm-select-2" defaultValue="Timezone">
          <SelectItem value="Timezone" text="Timezone" />
        </TimePickerSelect>
      </TimePicker>

      {/* default: 40px as before */}
      <TimePicker labelText="Choose a time">
        <TimePickerSelect id="tp-md-select-1" defaultValue="AM">
          <SelectItem value="AM" text="AM" />
          <SelectItem value="PM" text="PM" />
        </TimePickerSelect>
        <TimePickerSelect id="tp-md-select-2" defaultValue="Timezone">
          <SelectItem value="Timezone" text="Timezone" />
        </TimePickerSelect>
      </TimePicker>

      {/* large: expecting 48px but still 40px */}
      <TimePicker labelText="Choose a time" size="lg">
        <TimePickerSelect id="tp-lg-select-1" defaultValue="AM">
          <SelectItem value="AM" text="AM" />
          <SelectItem value="PM" text="PM" />
        </TimePickerSelect>
        <TimePickerSelect id="tp-lg-select-2" defaultValue="Timezone">
          <SelectItem value="Timezone" text="Timezone" />
        </TimePickerSelect>
      </TimePicker>
    </div>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
